#nullable enable // autogenerated

using MukioI18n;
using MVZ2.GameContent.Enemies;
using MVZ2.Vanilla.Definitions;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.RandomChina;
using MVZ2Logic.Level;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Tools.Random;
using UnityEngine;

namespace MVZ2.GameContent.RandomChinaEvents
{
    [RandomChinaEventDefinition(VanillaRandomChinaEventNames.driverless)]
    public class DriverlessEvent : RandomChinaEventDefinition
    {
        public DriverlessEvent(string nsp, string path) : base(nsp, path, NAME, DESCRIPTION, 9999999f)
        {
        }
        public override void Run(Entity contraption, RandomGenerator rng)
        {
            var level = contraption.Level;
            int maxLane = level.GetMaxLaneCount();
            var column = level.GetMaxColumnCount() - 1;
            var spawnParam = new SpawnParams();
            spawnParam.SetProperty(EngineEntityProps.FACTION, level.GetRightFaction());
            spawnParam.SetProperty(AxolotlSuit.PROP_EMPTY, true);
            for (int i = 0; i < maxLane; i++)
            {
                var position = level.GetEntityGridPosition(column, i) + Vector3.up * 800f;
                contraption.Spawn(VanillaEnemyID.axolotlSuit, position, spawnParam);
            }
        }
        [TranslateMsg("随机瓷器事件名称", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_NAME)]
        public const string NAME = "无人驾驶";
        [TranslateMsg("随机瓷器事件描述", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_DESCRIPTION)]
        public const string DESCRIPTION = "在最右侧生成一列无人驾驶的美西螈号机甲";
    }
}
